UPDATE email_templates
SET
    subject = 'Offer Letter - {{employee_name}}',
    body = E'Dear {{employee_name}},\n\nWe are pleased to offer you the position of **{{designation}}** at **{{company_name}}**.\n\n### 1. Employment Details\n\n* **Employee ID**: [Auto-generated]\n* **Department**: [Department Name]\n* **Designation**: [Designation]\n* **Work Location**: [Branch Name]\n\n### 2. Compensation\n\nYour compensation details are as follows:\n\n* **CTC**: ₹[Amount] per annum\n* Detailed salary structure will be shared separately.\n\n### 3. Profile Completion (Mandatory Step)\n\nAs part of onboarding, you are required to complete your profile by providing additional details such as:\n\n* Address & Personal Information\n* Bank Details\n* Identity Proof Documents\n* Educational & Experience Details\n\nPlease use the secure link below to complete your profile:\n\n👉 **Complete Your Profile**: [Profile Completion Link]\n\n**Note:**\n\n* This link is secure and valid until [Expiry Date].\n* You can access it without login.\n* Please ensure all details and documents are accurate.\n\n### 4. Verification & Approval\n\n* Your submitted details will be reviewed by our HR team.\n* In case of any discrepancies, you will receive a new link to update specific fields.\n* Final confirmation of employment is subject to successful verification.\n\n### 5. Terms & Conditions\n\n* You are required to join on or before the mentioned joining date.\n* All submitted documents must be genuine.\n* The company reserves the right to withdraw this offer if any information is found incorrect.\n\n### 6. Acceptance\n\nPlease confirm your acceptance of this offer by replying to this email.\n\nWe look forward to welcoming you to our organization.\n\nBest Regards,\n**[HR Name]**\n[Company Name]\n[Contact Details]'
WHERE template_key = 'OFFER_LETTER_TEMPLATE';
